import assert from 'node:assert/strict';
import { addTask, completeTask } from '../src/tasks.js';

// Test adding a valid task
let tasks = addTask([], 'Ship safely');
assert.equal(tasks.length, 1);
assert.equal(tasks[0].id, 1);
assert.equal(tasks[0].title, 'Ship safely');
assert.equal(tasks[0].done, false);

// Test completing a task
assert.equal(completeTask(tasks, 1)[0].done, true);

// Test adding a task with leading/trailing spaces
tasks = addTask([], '  Clean up  ');
assert.equal(tasks[0].title, 'Clean up');

// Test adding a task with an empty string
try {
  addTask(tasks, '');
  assert.fail('Expected error for empty title');
} catch (error) {
  assert.equal(error.message, 'Title must be a non-empty string.');
}

// Test adding a task with a non-string title
try {
  addTask(tasks, 123);
  assert.fail('Expected error for non-string title');
} catch (error) {
  assert.equal(error.message, 'Title must be a non-empty string.');
}

// Test unique IDs after removing a task
tasks = addTask([], 'Task 1');
tasks = addTask(tasks, 'Task 2');
tasks = tasks.filter(task => task.id !== 1); // Remove Task 1
tasks = addTask(tasks, 'Task 3');
assert.equal(tasks[2].id, 3);
